class Solution {
  public int subsequencePairCount(int[] nums) {
    final int MOD = 1_000_000_007;
    int max = 0;
    for (int v : nums) max = Math.max(max, v);
    int m = max + 1;
    int[][] gcd = new int[m][m];
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < m; j++) {
        int a = i, b = j;
        while (b != 0) {
          int t = a % b;
          a = b;
          b = t;
        }
        gcd[i][j] = a;
      }
    }
    int[][] dp = new int[m][m];
    dp[0][0] = 1;
    for (int x : nums) {
      int[][] nd = new int[m][m];
      for (int a = 0; a < m; a++) {
        for (int b = 0; b < m; b++) {
          int v = dp[a][b];
          if (v == 0) continue;
          nd[a][b] = (nd[a][b] + v) % MOD;
          int ga = gcd[a][x], gb = gcd[b][x];
          nd[ga][b] = (nd[ga][b] + v) % MOD;
          nd[a][gb] = (nd[a][gb] + v) % MOD;
        }
      }
      dp = nd;
    }
    long ans = 0;
    for (int g = 1; g < m; g++) ans += dp[g][g];
    return (int) (ans % MOD);
  }
}
